insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013f', '{"code":"TEC-21","title":"Pass and press – triangolo","area":"tecnica","fase":["attivazione"],"obiettivi":["passaggio","ricezione","controllo orientato","pressione"],"eta":"U8-U13","giocatori":"4 per triangolo (2 sul cinesino di partenza)","spazio":"Triangolo con lati di 8 m","durata":8,"materiale":"3 cinesini per triangolo, 1 pallone","perche":"Attivazione semplice con tanti passaggi e ricezioni sotto pressione: chi riceve deve controllare e passare con un avversario che arriva forte addosso.","descrizione":"Setup: triangolo di 3 cinesini. A e D sul primo cinesino, B sul secondo, C sul terzo.\nEsecuzione: A passa a B e lo pressa subito, forte. B controlla e passa a C, poi pressa subito C. C passa a D e pressa D, e così via. Chi pressa resta sul cinesino del compagno a cui ha passato: A va sul cinesino di B, B su quello di C, C su quello di partenza.\nSi gira sempre nello stesso verso, senza pause.","rotazione":"Chi passa pressa e prende il posto del compagno a cui ha passato. Dopo 2′ si cambia verso.","varianti":"Due tocchi obbligati (controllo + passaggio), poi un tocco. Controllo orientato lontano dal pressatore. Cambio verso al fischio. Triangolo più piccolo per aumentare la pressione.","coaching":"Passaggio forte e sul piede, poi scatto immediato a pressare. Chi pressa arriva veloce ma frena prima, senza togliere palla. Chi riceve guarda prima il compagno a cui passare, controlla lontano dal pressatore e passa prima che arrivi.","fonte":"Proposta di Andrea (23/10/2026)","diagram":{"field":{"preset":"spazio","w":12,"h":12},"steps":[{"title":"A passa a B","note":"A pressa subito B"},{"title":"B passa a C","note":"B pressa C, A resta sul cinesino di B"},{"title":"C passa a D","note":"C pressa D, B resta sul cinesino di C"},{"title":"D passa ad A","note":"D pressa A, C resta sul cinesino di partenza"},{"title":"A passa a B","note":"A pressa B"},{"title":"B passa a C","note":"B pressa C: tutti hanno cambiato cinesino"},{"title":"Si riparte"}],"items":[{"id":"it1132","type":"disc","pos":{"0":{"x":2,"y":10.6}}},{"id":"it1133","type":"disc","pos":{"0":{"x":10,"y":10.6}}},{"id":"it1134","type":"disc","pos":{"0":{"x":6,"y":3.7}}},{"id":"it1135","type":"playerA","label":"A","pos":{"0":{"x":2,"y":9.5},"1":{"x":8.5,"y":9.5},"2":{"x":10,"y":9.5},"5":{"x":6.75,"y":3.9},"6":{"x":6,"y":2.6}}},{"id":"it1136","type":"playerA","label":"D","pos":{"0":{"x":0.8,"y":10.8},"1":{"x":2,"y":9.5},"4":{"x":8.5,"y":9.5},"5":{"x":10,"y":9.5}}},{"id":"it1137","type":"playerA","label":"B","pos":{"0":{"x":10,"y":9.5},"2":{"x":6.75,"y":3.9},"3":{"x":6,"y":2.6},"6":{"x":2.75,"y":8.2},"7":{"x":0.8,"y":10.8}}},{"id":"it1138","type":"playerA","label":"C","pos":{"0":{"x":6,"y":2.6},"3":{"x":2.75,"y":8.2},"4":{"x":2,"y":9.5}}},{"id":"it1139","type":"ball","pos":{"0":{"x":2.6,"y":9.1},"1":{"x":9.4,"y":9.1},"2":{"x":6.4,"y":3.2},"3":{"x":2.6,"y":9.1},"4":{"x":9.4,"y":9.1},"5":{"x":6.4,"y":3.2},"6":{"x":2.6,"y":9.1}}}],"arrows":[{"id":"ar1140","kind":"pass","step":0,"from":{"x":2.6,"y":9.1},"to":{"x":9.4,"y":9.1}},{"id":"ar1141","kind":"run","step":0,"from":{"x":2,"y":9.5},"to":{"x":8.5,"y":9.5},"curve":-1},{"id":"ar1142","kind":"pass","step":1,"from":{"x":9.4,"y":9.1},"to":{"x":6.4,"y":3.2}},{"id":"ar1143","kind":"run","step":1,"from":{"x":10,"y":9.5},"to":{"x":6.75,"y":3.9},"curve":-1},{"id":"ar1144","kind":"pass","step":2,"from":{"x":6.4,"y":3.2},"to":{"x":2.6,"y":9.1}},{"id":"ar1145","kind":"run","step":2,"from":{"x":6,"y":2.6},"to":{"x":2.75,"y":8.2},"curve":-1},{"id":"ar1146","kind":"pass","step":3,"from":{"x":2.6,"y":9.1},"to":{"x":9.4,"y":9.1}},{"id":"ar1147","kind":"run","step":3,"from":{"x":2,"y":9.5},"to":{"x":8.5,"y":9.5},"curve":-1},{"id":"ar1148","kind":"pass","step":4,"from":{"x":9.4,"y":9.1},"to":{"x":6.4,"y":3.2}},{"id":"ar1149","kind":"run","step":4,"from":{"x":10,"y":9.5},"to":{"x":6.75,"y":3.9},"curve":-1},{"id":"ar1150","kind":"pass","step":5,"fr